style.css:
@-moz-document domain("youtube.com") {
/* 1. LA LÍNEA DEL TIEMPO: Se vuelve un hermoso Rosa */
    .ytp-play-progress.ytp-swatch-background-color, 
    .ytp-play-progress {
        background-color: #FF8AAB !important;
        background: #FF8AAB !important;
    }

    /* 2. EL STICKER DE MY MELODY: Reemplaza la bolita roja fea */
    .ytp-scrubber-button.ytp-swatch-background-color,
    .ytp-scrubber-button {
        background: url('https://icons8.com') no-repeat center !important;
        background-size: contain !important;
        width: 32px !important;  /* Tamaño ideal para que se vea claro */
        height: 32px !important;
        transform: scale(1) !important;
        border-radius: 0% !important; /* Quita el círculo rojo original */
        border: none !important;
        box-shadow: none !important;
    }

    /* Forzamos que se mantenga visible la carita aunque el video esté reproduciéndose */
    .ytp-chrome-controls .ytp-scrubber-container {
        opacity: 1 !important;
    }
}
